function queryString(query: object): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    if (value === undefined || value === null || value === '') return;
    params.set(key, String(value));
  });
  const text = params.toString();
  return text ? `?${text}` : '';
}

export async function listOrderIssues(query: OrderIssueFilterQuery = {}): Promise<OrderIssueListItem[]> {
  const res = await apiClient.get<BffResponse<OrderIssueListItem[]>>(`/sales/order-issues${queryString(query)}`);
  return unwrap(res);
}

export async function getOrderIssue(sttRec: string): Promise<OrderIssueDetail> {
  const res = await apiClient.get<BffResponse<OrderIssueDetail>>(`/sales/order-issues/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createOrderIssue(body: OrderIssueWriteBody): Promise<OrderIssueDetail> {
  const res = await apiClient.post<BffResponse<OrderIssueDetail>>('/sales/order-issues', body);
  return unwrap(res);
}

export async function updateOrderIssue(sttRec: string, body: OrderIssueWriteBody): Promise<OrderIssueDetail> {
  const res = await apiClient.put<BffResponse<OrderIssueDetail>>(`/sales/order-issues/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}

export async function deleteOrderIssue(sttRec: string): Promise<boolean> {
  const res = await apiClient.delete<BffResponse<boolean>>(`/sales/order-issues/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function pullOrderIssueFromCommand(query: { lenhSo: string; ngayCt?: string; sttRec?: string }): Promise<OrderIssueFromCommand> {
  const res = await apiClient.get<BffResponse<OrderIssueFromCommand>>(`/sales/order-issues/from-commands${queryString(query)}`);
  return unwrap(res);
}
